STSales={}
local function reply(s,ok,msg,data)TriggerClientEvent('st-core:client:saleContractResult',s,{ok=ok,message=msg,data=data})end
local function sig(v)if type(v)~='string'or#v<100 or#v>100000 or not v:match('^data:image/png;base64,')then return nil end;return v end
local function number()for _=1,50 do local n=('ST-DMV-%s-%06d'):format(os.date('%Y%m%d'),math.random(0,999999));if not MySQL.single.await('SELECT id FROM st_vehicle_sale_contracts WHERE contract_number=? LIMIT 1',{n})then return n end end end
local function near(a,b,d)if not b then return false end;local x,y=GetPlayerPed(a),GetPlayerPed(b);if x<=0 or y<=0 then return false end;return #(GetEntityCoords(x)-GetEntityCoords(y))<=(d or 5.0)end
local function vehicleNear(s,d)local p=GetPlayerPed(s);if p<=0 then return end;local c=GetEntityCoords(p);local best,bd;for _,v in ipairs(GetAllVehicles())do local n=#(c-GetEntityCoords(v));if n<=(d or 8.0)and(not bd or n<bd)then best,bd=v,n end end;return best end
local function contract(id)return MySQL.single.await('SELECT * FROM st_vehicle_sale_contracts WHERE id=? LIMIT 1',{tonumber(id)})end
local function playerFor(id)for _,p in ipairs(GetPlayers())do local s=tonumber(p);if STPayments.GetIdentifier(s)==id then return s end end end
local function item(s,slot,id)if GetResourceState('ox_inventory')~='started'then return false,'ox_inventory_not_started'end;local x=exports.ox_inventory:GetSlot(s,tonumber(slot));if not x or x.name~=Config.Documents.VehicleSaleContractItem then return false,'contract_item_not_found'end;if not x.metadata or tostring(x.metadata.contract_id)~=tostring(id)then return false,'contract_item_mismatch'end;return true,x end
local function audit(actor,id,action,meta)pcall(function()MySQL.insert.await('INSERT INTO st_dmv_document_audit (document_type,document_id,actor_identifier,action,metadata) VALUES (?,?,?,?,?)',{'vehicle_sale_contract',tostring(id),actor,action,meta and json.encode(meta)or nil})end)end
local function data(c,slot)return{id=c.id,contractNumber=c.contract_number,status=c.status,slot=slot,vehicleIdentifier=c.vehicle_identifier,vin=c.vin,plate=c.plate,vehicleModel=c.vehicle_model,vehicleDisplayName=c.vehicle_display_name,sellerName=c.seller_name,buyerName=c.buyer_name,sellerIdentifier=c.seller_identifier,buyerIdentifier=c.buyer_identifier,salePrice=tonumber(c.sale_price)or 0,sellerSignature=c.seller_signature,buyerSignature=c.buyer_signature,sellerSignedAt=c.seller_signed_at,buyerSignedAt=c.buyer_signed_at,expiresAt=c.expires_at}end
local function atDMV(s)local c=GetEntityCoords(GetPlayerPed(s));for _,l in ipairs(Config.DMV.Locations or{})do if #(c-vector3(l.x,l.y,l.z))<=5.0 then return true end end;return false end
RegisterNetEvent('st-core:server:issueSaleContract',function()local s=source;local id=STPayments.GetIdentifier(s);if not id then return reply(s,false,'Unable to identify your character.')end;if not atDMV(s)then return reply(s,false,'You must be at the DMV to request a sale contract.')end;local n=number();if not n then return reply(s,false,'The DMV contract system is temporarily unavailable.')end;local now=os.time();local exp=now+((Config.Documents.ContractValidityDays or 7)*86400);local cid=MySQL.insert.await([[INSERT INTO st_vehicle_sale_contracts(contract_number,seller_identifier,seller_name,issued_at,expires_at,status,vehicle_identifier,vin,plate,buyer_identifier,buyer_name)VALUES(?,?,?,?,?,'draft','','','','','')]],{n,id,STPayments.GetName(s)or'Unknown',now,exp});if not cid then return reply(s,false,'Unable to issue the sale contract.')end;local meta={contract_id=cid,contract_number=n,status='draft',description=('DMV Vehicle Sale Contract %s'):format(n)};if not exports.ox_inventory:CanCarryItem(s,Config.Documents.VehicleSaleContractItem,1,meta)or not exports.ox_inventory:AddItem(s,Config.Documents.VehicleSaleContractItem,1,meta)then MySQL.update.await("UPDATE st_vehicle_sale_contracts SET status='cancelled' WHERE id=?",{cid});return reply(s,false,'Unable to place the contract in your inventory.')end;audit(id,cid,'issued',{contract_number=n});reply(s,true,('Sale contract %s issued.'):format(n))end)
RegisterNetEvent('st-core:server:useSaleContract',function(d)local s=source;if type(d)~='table'then return end;local id=STPayments.GetIdentifier(s);local ok,e=item(s,d.slot,d.contractId);if not ok then return reply(s,false,e)end;local c=contract(d.contractId);if not c then return reply(s,false,'This contract no longer exists.')end;if c.expires_at<os.time()and c.status~='completed'then MySQL.update.await("UPDATE st_vehicle_sale_contracts SET status='expired' WHERE id=?",{c.id});return reply(s,false,'This contract has expired.')end;if c.status=='draft'and c.vehicle_identifier==''then if c.seller_identifier~=id then return reply(s,false,'Only the seller who requested this contract can start it.')end;local b=tonumber(d.buyerServerId);if not b or b==s or GetPlayerPed(b)<=0 or not near(s,b,Config.Sales.BuyerDistance)then return reply(s,false,'The buyer must be standing next to you.')end;local v=vehicleNear(s,Config.Sales.VehicleDistance);if not v then return reply(s,false,'Stand next to the vehicle you are selling.')end;local plate=STValidation.NormalizePlate(GetVehicleNumberPlateText(v));local r=STVehicles.GetRegistrationByPlate(plate);if not r or r.status~='active'or r.owner_identifier~=id then return reply(s,false,'That vehicle is not actively registered to you.')end;local bid=STPayments.GetIdentifier(b);if not bid then return reply(s,false,'Unable to identify the buyer.')end;if MySQL.update.await("UPDATE st_vehicle_sale_contracts SET vehicle_identifier=?,vin=?,plate=?,vehicle_model=?,vehicle_display_name=?,buyer_identifier=?,buyer_name=? WHERE id=? AND status='draft' AND seller_identifier=?",{r.vehicle_identifier,r.vin,r.plate,r.vehicle_model,r.vehicle_display_name or r.vehicle_model,bid,STPayments.GetName(b)or'Unknown',c.id,id})~=1 then return reply(s,false,'The contract was already started or changed.')end;c=contract(c.id)end;if c.status=='draft'and c.vehicle_identifier~=''or c.status=='seller_signed'or c.status=='buyer_signed'then if c.status~='draft'and c.buyer_identifier~=id and c.seller_identifier~=id then return reply(s,false,'You are not a party to this contract.')end;TriggerClientEvent('st-core:client:saleContract',s,data(c,d.slot));return end;reply(s,false,'This contract cannot be opened.')end)
RegisterNetEvent('st-core:server:sellerSignSaleContract',function(d)local s=source;if type(d)~='table'then return end;local id=STPayments.GetIdentifier(s);local signature=sig(d.signature);local price=tonumber(d.salePrice);local c=contract(d.contractId);if not signature or not price or price<=0 or price>1000000000 then return reply(s,false,'Valid signature and sale price are required.')end;if not c or c.status~='draft'or c.seller_identifier~=id then return reply(s,false,'This contract is no longer available for seller signature.')end;local b=playerFor(c.buyer_identifier);if not near(s,b,Config.Sales.BuyerDistance)then return reply(s,false,'The buyer must remain nearby.')end;local r=STVehicles.GetRegistration(c.vehicle_identifier);if not r or r.owner_identifier~=id or r.plate~=c.plate then return reply(s,false,'Vehicle ownership changed before signing.')end;if STTitles.HasActiveLien(c.vehicle_identifier)then return reply(s,false,'This vehicle has an active lien and cannot be transferred until the lien is released.')end;if MySQL.update.await("UPDATE st_vehicle_sale_contracts SET sale_price=?,seller_signature=?,seller_signed_at=?,status='seller_signed' WHERE id=? AND status='draft'",{price,signature,os.time(),c.id})~=1 then return reply(s,false,'Unable to sign the contract.')end;audit(id,c.id,'seller_signed',{sale_price=price});TriggerClientEvent('st-core:client:saleContract',s,data(contract(c.id),d.slot))end)
RegisterNetEvent('st-core:server:buyerSignSaleContract',function(d)local s=source;if type(d)~='table'then return end;local id=STPayments.GetIdentifier(s);local signature=sig(d.signature);local c=contract(d.contractId);if not signature then return reply(s,false,'A valid buyer signature is required.')end;if not c or c.status~='seller_signed'or c.buyer_identifier~=id then return reply(s,false,'This contract is not available for your signature.')end;if c.expires_at<os.time()then return reply(s,false,'This contract has expired.')end;local seller=playerFor(c.seller_identifier);if not near(s,seller,Config.Sales.BuyerDistance)then return reply(s,false,'The seller must remain nearby.')end;local r=STVehicles.GetRegistration(c.vehicle_identifier);if not r or r.owner_identifier~=c.seller_identifier or r.plate~=c.plate then return reply(s,false,'The vehicle is no longer owned by the seller.')end;if STTitles.HasActiveLien(c.vehicle_identifier)then return reply(s,false,'This vehicle has an active lien and cannot be transferred.')end;if MySQL.update.await("UPDATE st_vehicle_sale_contracts SET buyer_signature=?,buyer_signed_at=?,status='buyer_signed' WHERE id=? AND status='seller_signed'",{signature,os.time(),c.id})~=1 then return reply(s,false,'Unable to record the buyer signature.')end;audit(id,c.id,'buyer_signed',{sale_price=c.sale_price});TriggerClientEvent('st-core:client:saleContract',s,data(contract(c.id),d.slot))end)
RegisterNetEvent('st-core:server:submitSaleContract',function(d)local s=source;if type(d)~='table'then return end;local id=STPayments.GetIdentifier(s);local c=contract(d.contractId);if not c or c.status~='buyer_signed'or c.buyer_identifier~=id then return reply(s,false,'Only the named buyer can submit this fully signed contract.')end;if not atDMV(s)then return reply(s,false,'You must be at the DMV to complete the transfer.')end;local r=STVehicles.GetRegistration(c.vehicle_identifier);if not r or r.owner_identifier~=c.seller_identifier or r.plate~=c.plate then return reply(s,false,'The seller no longer owns this vehicle.')end;if STTitles.HasActiveLien(c.vehicle_identifier)then return reply(s,false,'The vehicle has an active lien. Release the lien before transfer.')end;local fee=tonumber(Config.Registration.TransferFee)or 0;local paid,err=STPayments.Charge(s,fee,'DMV vehicle ownership transfer');if not paid then return reply(s,false,err=='insufficient_funds'and'Insufficient funds for the DMV transfer fee.'or'Transfer payment failed.')end;local now=os.time();local exp=now+((Config.Registration.DurationDays or 30)*86400);local framework=GetResourceState('qb-core')=='started'and'qbcore'or(GetResourceState('es_extended')=='started'and'esx'or nil);if not framework then return reply(s,false,'Unsupported framework; transfer cancelled.')end;local ownerQuery=framework=='qbcore'and'UPDATE player_vehicles SET citizenid=? WHERE citizenid=? AND plate=?'or'UPDATE owned_vehicles SET owner=? WHERE owner=? AND plate=?';local tx={{ownerQuery,{id,c.seller_identifier,c.plate}},{"UPDATE st_vehicle_registrations SET owner_identifier=?,owner_name=?,registered_at=?,expires_at=?,status='active',updated_at=CURRENT_TIMESTAMP WHERE id=? AND owner_identifier=?",{id,c.buyer_name,now,exp,r.id,c.seller_identifier}},{"UPDATE st_vehicle_records SET owner_identifier=?,owner_name=?,registration_status='active',registration_expires_at=?,updated_at=CURRENT_TIMESTAMP WHERE vehicle_identifier=?",{id,c.buyer_name,exp,c.vehicle_identifier}},{"UPDATE st_vehicle_insurance SET status='cancelled',cancellation_reason='Vehicle transferred to new owner',updated_at=CURRENT_TIMESTAMP WHERE vehicle_identifier=? AND owner_identifier=? AND status='active'",{c.vehicle_identifier,c.seller_identifier}},{"UPDATE st_vehicle_titles SET owner_identifier=?,owner_name=?,issue_date=?,title_status='clear',updated_at=CURRENT_TIMESTAMP WHERE vehicle_identifier=? AND owner_identifier=?",{id,c.buyer_name,now,c.vehicle_identifier,c.seller_identifier}},{"INSERT INTO st_vehicle_transfer_audit(contract_id,vehicle_identifier,vin,old_owner_identifier,old_owner_name,new_owner_identifier,new_owner_name,sale_price,old_plate,new_plate,transferred_at)VALUES(?,?,?,?,?,?,?,?,?,?,?)",{c.id,c.vehicle_identifier,c.vin,c.seller_identifier,c.seller_name,id,c.buyer_name,c.sale_price,c.plate,c.plate,now}},{"UPDATE st_vehicle_sale_contracts SET status='completed',completed_at=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='buyer_signed'",{now,c.id}}};if not MySQL.transaction.await(tx)then return reply(s,false,'The ownership transfer failed. No ownership was changed.')end;STVehicles.SyncVehicleRecord(c.vehicle_identifier);audit(id,c.id,'dmv_transfer_completed',{sale_price=c.sale_price,insurance_required=true});local title=STTitles.Get(c.vehicle_identifier);local reg=STVehicles.GetRegistration(c.vehicle_identifier);pcall(function()exports[GetCurrentResourceName()]:CreateTitleDocument(s,title)end);pcall(function()exports[GetCurrentResourceName()]:CreateRegistrationDocument(s,reg)end);TriggerClientEvent('st-core:client:insuranceRequired',s,{vehicleIdentifier=c.vehicle_identifier,plate=c.plate,message='Vehicle transferred. Active liability insurance is required before the vehicle may be legally operated.'});reply(s,true,'Ownership transferred. New title and registration issued; insurance is required before driving.',{vehicleIdentifier=c.vehicle_identifier,plate=c.plate,title=title,registration=reg,insuranceRequired=true})end)
CreateThread(function()while true do Wait(300000);if Config.Sales.AutoCancelExpiredContracts then MySQL.update.await("UPDATE st_vehicle_sale_contracts SET status='expired',updated_at=CURRENT_TIMESTAMP WHERE status IN ('draft','seller_signed','buyer_signed')AND expires_at<?",{os.time()})end end end)
exports('GetVehicleSaleContract',contract)
